  assert.deepEqual([...calls].sort((a, b) => a - b), Array.from({ length: 75 }, (_, k) => k + 1));
  for (const did of ['did:plc:aaa', 'did:plc:bbb', 'did:plc:nhlcvrqwh7hwhvmgxbut6c2f']) {
